import type { RowDataPacket, ResultSetHeader } from 'mysql2';
import { pool } from './mysql';

export interface User {
  userId: number;
  googleId: string;
  email: string;
  firstName: string;
  lastName: string;
  birthYear: number;
}

// fields needed to add a user, the id is generated by MySQL
export type NewUser = Omit<User, 'userId'>;

// a row of the users table as mysql2 returns it
interface UserRow extends RowDataPacket {
  user_id: number;
  google_id: string;
  email: string;
  first_name: string;
  last_name: string;
  birth_year: number;
}

function toUser(row: UserRow): User {
  return {
    userId: row.user_id,
    googleId: row.google_id,
    email: row.email,
    firstName: row.first_name,
    lastName: row.last_name,
    birthYear: row.birth_year,
  };
}

// adds a user and returns their new user_id, throws ER_DUP_ENTRY if the google_id already exists
export async function createUser(user: NewUser): Promise<number> {
  const [result] = await pool.execute<ResultSetHeader>(
    `INSERT INTO users (google_id, email, first_name, last_name, birth_year)
     VALUES (?, ?, ?, ?, ?)`,
    [user.googleId, user.email, user.firstName, user.lastName, user.birthYear],
  );
  return result.insertId;
}

export async function findUserByGoogleId(googleId: string): Promise<User | null> {
  const [rows] = await pool.execute<UserRow[]>(
    `SELECT user_id, google_id, email, first_name, last_name, birth_year
     FROM users WHERE google_id = ? LIMIT 1`,
    [googleId],
  );
  const row = rows[0];
  return row ? toUser(row) : null;
}

export async function userExists(googleId: string): Promise<boolean> {
  const [rows] = await pool.execute<RowDataPacket[]>(
    'SELECT 1 FROM users WHERE google_id = ? LIMIT 1',
    [googleId],
  );
  return rows.length > 0;
}

// true when a query failed because a unique key (e.g. google_id) already exists
export function isDuplicateEntryError(error: unknown): boolean {
  return (error as { code?: string } | null)?.code === 'ER_DUP_ENTRY';
}
